clearScene();setBig(null);setEq(null);
var G=[["松弛解","a + c + 4/7 的 f","值 22.857"],
       ["向上取整","a + c + 整个 f","重量 15 > 12，装不下"],
       ["向下取整","a + c","值 16，离 22 差得远"]];
matrix({rows:3,cols:3,cw:270,ch:56,x:235,y:180,
  cell:function(i,j){return G[i][j];},
  hl:function(i,j){return i===1&&j===2?"hl3":(i===2&&j===2?"hl3":"");},
  label:"把分数解圆成整数，两条路都不通"});
setCap("向上<b>装不下</b>，向下<b>差太远</b>。松弛解<s>不能当解用</s>。");

clearScene();setBig(null);setEq(null);
axes({l:300,r:980,t:190,b:330});
dots([[620,330],[860,330]],"",14);
curve([[300,330],[860,330]],"fit g");
note("真最优只可能落在这一段里",560,300,"g");
note("22",620,356,"g");
note("22.857",860,356,"b");
note("目标全是整数 ⇒ 上界可以收成 ≤ 22",640,386,"y");
setCap("界的用法不是「约等于」，是 <b>保证</b>：再好也好不过这个数。");

clearScene();setBig(null);setEq(null);
lamps({y:208,r:32,gap:300,items:[
 {label:"当解用",sub:"不可行或差很远",state:"dead"},
 {label:"取整用",sub:"两边都不通",state:"dead"},
 {label:"当界用",sub:"永远成立的保证",state:"on"}],
 caption:"松弛的产品只有第三个"});
setCap("回到第 2 拍：<b>它根本不是拿来当答案的</b>。");

clearScene();setBig(null);setEq(null);
curve([[380,340],[380,200],[580,170],[780,240],[700,340],[380,340]],"fit b");
arrow(470,310,540,270,"y");arrow(540,270,610,230,"y");arrow(610,230,660,205,"y");
note("一步一步往高处爬",520,372,"");
note("可线性目标<b>没有内点极值</b>",900,230,"r","start");
note("梯度处处相同，爬到边界就卡住",900,266,"r","start");
setCap("对一般的连续优化这是对的。可线性问题<b>有更强的结构</b>没被用上。");

clearScene();setBig(null);setEq(null);
curve([[380,340],[380,200],[580,170],[780,240],[700,340],[380,340]],"fit b");
dots([[580,170]],"c",16);
link(420,300,840,180);link(400,330,820,210);
note("等值线：目标相同的点连成一条直线",640,372,"");
note("把等值线往目标变好的方向推",870,210,"y","start");
note("最后离开可行域的那一刻，碰到的是顶点",870,246,"g","start");
setCap("推到最后<b>一定停在角上</b>。这就是为什么只需要看顶点。");

clearScene();setBig(null);setEq(null);
boxNode(165,168,420,96,"最坏情况","r");
boxNode(715,168,420,96,"实践中","g");
note("Klee 与 Minty 造了个扰动立方体",375,308,"r");
note("单纯形会走遍它的每一个顶点",375,340,"r");
note("几十年工业使用，极快",925,308,"g");
note("而且另有多项式算法（内点法）",925,340,"g");
note("MIP 求解器在搜索树的每个节点都要解一次 LP",640,382,"y");
setCap("「有限」不等于「快」。<b>这件事必须诚实地说清楚</b>。");

clearScene();setBig(null);setEq(null);
bars({vals:[99,29],max:99,x:430,y:348,w:420,h:170,
  cls:function(i){return i===0?"r":"g";}});
note("不用界：99 个节点",535,374,"r");
note("用 LP 界剪：29 个",745,374,"g");
setCap("同一个背包、同一棵树、同样的最优解 <b>22</b>。只多了一件事：<b>先问界</b>。");

clearScene();setBig(null);setEq(null);
boxNode(200,170,430,98,"都是分支 + 回溯","y");
arrow(660,219,775,219,"r");
boxNode(800,170,310,98,"所以是一回事","y");
note("都在搜索树上走",415,310,"");
note("都是走不通就退回来",415,342,"");
note("连名字都叫分支定界",955,310,"");
note("可「定界」那两个字是新的",955,342,"r");
setCap("形状确实一样。<b>可剪枝的理由完全不同</b> —— 这是整集的轴。");

clearScene();setBig(null);setEq(null);
tree({r:22,nodes:[
 {id:0,parent:null,x:640,y:178,label:"LP"},
 {id:1,parent:0,x:450,y:276,label:"≤ 手上的"},
 {id:2,parent:0,x:840,y:276,label:"> 手上的"}]});
note("整棵子树砍掉，一个点都不看",450,330,"g");
note("还有希望 ⇒ 继续分支",840,330,"y");
note("Land 与 Doig 1960 把这一套写成了算法",640,382,"");
setCap("<b>界不如手上的解 ⇒ 整棵子树直接扔</b>。这一步叫 bound pruning。");

clearScene();setBig(null);setEq(null);
tree({r:19,nodes:[
 {id:0,parent:null,x:640,y:172,label:"22.86"},
 {id:1,parent:0,x:430,y:250,label:"22.4"},
 {id:2,parent:0,x:850,y:250,label:"21.3"},
 {id:3,parent:1,x:330,y:330,label:"22"},
 {id:4,parent:1,x:530,y:330,label:"21.8"},
 {id:5,parent:2,x:760,y:330,label:"✂"},
 {id:6,parent:2,x:940,y:330,label:"✂"}]});
note("找到整数解 22",330,366,"g");
note("界 21.3 < 22 ⇒ 这一整边不用看",850,382,"r");
setCap("incumbent 一跳到 <b>22</b>，所有界 ≤ 22 的子树<b>当场全部作废</b>。");

clearScene();setBig(null);setEq(null);
var G=[["","剪掉的是什么路","凭什么敢剪"],
       ["L10 传播","走不通的路","域被删空 ⇒ 不可行"],
       ["L12 定界","走得通但不够好的路","界 ≤ 手上的解"]];
matrix({rows:3,cols:3,cw:265,ch:54,x:235,y:180,
  cell:function(i,j){return G[i][j];},
  hl:function(i,j){return i===2?"hl2":"";},
  label:"同样在砍，砍的根据不同"});
setCap("⚠ 定界剪掉的路上<b>有可行解</b> —— 只是都不够好。");

clearScene();setBig(null);setEq(null);
boxNode(170,168,420,100,"分支","b");
boxNode(700,168,420,100,"定界","v");
note("L10 已经讲透了",380,308,"");
note("拆成穷尽的几块",380,340,"b");
note("这一讲的新东西",910,308,"");
note("先算「最好能多好」，再决定要不要走",910,340,"v");
note("名字里的两个词，各占一半",640,382,"y");
setCap("<b>分支</b>是 L10 的；<b>定界</b>是这一讲的。合起来才是分支定界。");
